const cfg = $input.first().json || {};

function toStr(v) {
  return typeof v === 'string' ? v.trim() : '';
}

function slugify(input) {
  return String(input || '')
    .trim()
    .toLowerCase()
    .replace(/[\\\s]+/g, '-')
    .replace(/[^a-z0-9а-яё._-]/gi, '-')
    .replace(/-+/g, '-')
    .replace(/^[-._]+|[-._]+$/g, '')
    .slice(0, 80);
}

function normalizeBackend(rawBackend, text) {
  const raw = String(rawBackend || '').toLowerCase();
  const low = String(text || '').toLowerCase();

  if (raw.includes('gdrive') || raw.includes('google')) return 'gdrive';
  if (raw.includes('dropbox')) return 'dropbox';
  if (raw.includes('s3') || raw.includes('minio')) return 's3';
  if (raw.includes('git')) return 'github';

  if (/(google drive|gdrive|гугл драйв)/i.test(low)) return 'gdrive';
  if (/(dropbox|дропбокс)/i.test(low)) return 'dropbox';
  if (/(s3|minio)/i.test(low)) return 's3';

  return 'github';
}

const actionAliases = {
  upsert: ['upsert', 'write', 'append', 'save', 'remember', 'store', 'запомни', 'сохрани', 'запиши', 'добавь в память'],
  search: ['search', 'find', 'lookup', 'поиск', 'найди', 'вспомни', 'что помнишь'],
  get_file: ['get_file', 'read', 'open', 'прочитай', 'покажи файл'],
  list_files: ['list_files', 'list', 'files', 'список файлов', 'покажи файлы'],
  archive_weekly: ['archive_weekly', 'archive', 'weekly archive', 'архив', 'заархивируй'],
  compact: ['compact', 'compress', 'shrink', 'сожми', 'уплотни', 'очисти старое'],
  sync: ['sync', 'health_check', 'heartbeat', 'синхронизируй', 'проверь память', 'пинг памяти'],
};

function normalizeAction(raw) {
  const source = String(raw || '').toLowerCase().trim();
  if (!source) return '';

  for (const [name, aliases] of Object.entries(actionAliases)) {
    if (name === source || aliases.includes(source)) return name;
  }

  if (source.includes('archive')) return 'archive_weekly';
  if (source.includes('list')) return 'list_files';
  if (source.includes('read') || source.includes('file')) return 'get_file';
  if (source.includes('search') || source.includes('find')) return 'search';
  if (source.includes('compact') || source.includes('compress')) return 'compact';
  if (source.includes('sync') || source.includes('health')) return 'sync';
  if (source.includes('write') || source.includes('save') || source.includes('append')) return 'upsert';

  return '';
}

function inferAction(text, hasContent) {
  const low = String(text || '').toLowerCase();

  if (/(архив|archive)/i.test(low)) return 'archive_weekly';
  if (/(сожми|уплотни|compact|compress)/i.test(low)) return 'compact';
  if (/(список файлов|list files|list memory files)/i.test(low)) return 'list_files';
  if (/(прочитай|read file|get file|покажи файл)/i.test(low)) return 'get_file';
  if (/(найди|поиск|search|find|вспомни)/i.test(low)) return 'search';
  if (/(синх|heartbeat|health check|проверь память)/i.test(low)) return 'sync';
  if (/(запомни|сохрани|запиши|remember|save to memory|append)/i.test(low)) return 'upsert';

  if (hasContent) return 'upsert';
  return 'sync';
}

function extractKeyFromPath(path) {
  const p = String(path || '').trim();
  if (!p) return '';
  const file = p.split('/').pop() || '';
  return slugify(file.replace(/\.md$/i, ''));
}

function extractKeyFromText(text) {
  const low = String(text || '').trim();
  if (!low) return '';

  const m1 = low.match(/(?:тема|ключ|раздел|topic|key)\s*[:=]\s*([a-zа-яё0-9 _.-]{2,80})/i);
  if (m1 && m1[1]) return slugify(m1[1]);

  const m2 = low.match(/#([a-zа-яё0-9_-]{2,50})/i);
  if (m2 && m2[1]) return slugify(m2[1]);

  return '';
}

const textParts = [
  cfg.user_message,
  cfg.message,
  cfg.command,
  cfg.prompt,
  cfg.query,
  cfg.content,
  cfg.text,
  cfg.note,
].map(toStr).filter(Boolean);

const joinedText = textParts.join('\n').trim();
const explicitAction = normalizeAction(cfg.action || cfg.mode);
const hasContent = Boolean(toStr(cfg.content) || toStr(cfg.text) || toStr(cfg.note));
let action = explicitAction || inferAction(joinedText, hasContent);

const rawContent = toStr(cfg.content) || toStr(cfg.text) || toStr(cfg.note);
let content = rawContent;
let query = toStr(cfg.query);

if (action === 'upsert' && !content && joinedText) {
  content = joinedText;
}

if (action === 'search' && !query) {
  query = joinedText || content;
}

const smallTalk = /^(привет|hello|hi|ok|ау|test|тест)\W*$/i.test(content || joinedText);
const warnings = [];
if (!explicitAction && action === 'upsert' && smallTalk) {
  action = 'sync';
  warnings.push('small_talk_detected');
}
if (action === 'upsert' && (content || '').length < 12) {
  warnings.push('short_content');
}
if (action === 'search' && !query) {
  warnings.push('empty_query');
}

const backend = normalizeBackend(cfg.storage_backend || cfg.backend, joinedText);
const memoryKey = slugify(toStr(cfg.memory_key) || toStr(cfg.key) || extractKeyFromPath(cfg.path) || extractKeyFromText(joinedText) || 'general');

const priorityMap = {
  archive_weekly: 'high',
  compact: 'high',
  sync: 'normal',
  upsert: 'normal',
  search: 'normal',
  get_file: 'normal',
  list_files: 'low',
};

const confidence = explicitAction ? 0.95 : (warnings.length ? 0.68 : 0.82);

const existingMeta = (cfg.meta && typeof cfg.meta === 'object') ? cfg.meta : {};
const brainMeta = {
  version: '1.0.0',
  inferred: !explicitAction,
  confidence,
  priority: priorityMap[action] || 'normal',
  trigger_source: cfg.trigger_source || 'tool',
  warnings,
};

return [{
  json: {
    ...cfg,
    action,
    storage_backend: backend,
    memory_key: memoryKey,
    content,
    query,
    brain: {
      action,
      storage_backend: backend,
      confidence,
      priority: priorityMap[action] || 'normal',
      warnings,
      source_preview: joinedText.slice(0, 220),
    },
    meta: {
      ...existingMeta,
      brain: {
        ...(existingMeta.brain || {}),
        ...brainMeta,
      },
    },
  },
}];

const cfg = $input.first().json || {};
const backend = String(cfg.storage_backend || 'github').toLowerCase();
const missing = [];

if (backend === 'github') {
  const token = String(cfg.github_token || '').trim();
  if (!token || token.length < 20 || token.includes('REPLACE_')) {
    missing.push('MEMORY_GITHUB_TOKEN');
  }
}

if (backend === 'gdrive' && !String(cfg.connector_gdrive_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_GDRIVE_URL');
}
if (backend === 'dropbox' && !String(cfg.connector_dropbox_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_DROPBOX_URL');
}
if (backend === 's3' && !String(cfg.connector_s3_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_S3_URL');
}

const validateStatus = missing.length ? 'error' : 'ok';
const output = validateStatus === 'ok'
  ? `MEMORY_AGENT: конфиг валиден, backend=${backend}, action=${cfg.action || 'sync'}.`
  : `MEMORY_AGENT: отсутствуют настройки: ${missing.join(', ')}.`;

return [{
  json: {
    ...cfg,
    storage_backend: backend,
    validate_status: validateStatus,
    output,
    missing,
  },
}];

const cfg = $input.first().json || {};

const action = String(cfg.action || 'sync').toLowerCase();
const owner = String(cfg.github_owner || 'MaxCorpOrg');
const repo = String(cfg.github_repo || 'memory');
const branch = String(cfg.github_branch || 'main');
const basePath = String(cfg.memory_base_path || 'memory').replace(/(^\/+|\/+$/g, ''));
const archiveRoot = String(cfg.memory_archive_path || '_archive').replace(/(^\/+|\/+$/g, ''));
const heartbeatRel = String(cfg.memory_heartbeat_path || '_system/heartbeat.md').replace(/^\/+/, '');
const ghApi = String(cfg.github_api || 'https://api.github.com');
const githubToken = String(cfg.github_token || '');

const maxRepoBytes = Number(cfg.max_repo_bytes || 5 * 1024 * 1024);
const maxFileBytes = Number(cfg.max_file_bytes || 180000);
const keepRecentLines = Number(cfg.keep_recent_lines || 220);
const maxScanFiles = Number(cfg.max_scan_files || 30);
const maxResults = Number(cfg.max_results || 20);
const maxCompactFiles = Number(cfg.max_compact_files || 10);
const maxArchiveFiles = Number(cfg.max_archive_files || 15);

function nowIso() {
  return new Date().toISOString();
}

function datePart(iso) {
  return String(iso || nowIso()).slice(0, 10);
}

function getWeekId(d = new Date()) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
  return `${date.getUTCFullYear()}-W${String(weekNo).padStart(2, '0')}`;
}

function sanitizePathPart(input) {
  return String(input || 'memory')
    .trim()
    .replace(/[\\\s]+/g, '-')
    .replace(/[^a-zA-Z0-9._/-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^[-/.]+|[-/.]+$/g, '')
    .slice(0, 180) || 'memory';
}

function buildMemoryPath() {
  if (cfg.path) {
    return sanitizePathPart(String(cfg.path)).replace(/^\/+/, '');
  }
  const key = sanitizePathPart(cfg.memory_key || cfg.key || cfg.topic || 'general');
  return `${basePath}/${key}.md`;
}

function makeSnippet(lines, index, radius = 2) {
  const start = Math.max(0, index - radius);
  const end = Math.min(lines.length, index + radius + 1);
  return lines.slice(start, end).join('\n');
}

function parseDate(v) {
  const t = String(v || '').trim();
  if (!t) return null;
  const d = new Date(t);
  return Number.isNaN(d.getTime()) ? null : d;
}

function inRange(d, from, to) {
  if (!d) return true;
  if (from && d < from) return false;
  if (to && d > to) return false;
  return true;
}

const ghHeaders = {
  Authorization: `Bearer ${githubToken}`,
  Accept: 'application/vnd.github+json',
  'User-Agent': 'memory-neuro-agent',
};

const repoBase = `${ghApi}/repos/${owner}/${repo}`;

async function ghGet(url) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: ghHeaders,
    json: true,
    timeout: 60000,
  });
}

async function getContent(path) {
  const cleanPath = String(path || '').replace(/^\/+/, '');
  try {
    const data = await ghGet(`${repoBase}/contents/${encodeURIComponent(cleanPath)}?ref=${encodeURIComponent(branch)}`);
    const text = Buffer.from(String(data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
    return { exists: true, sha: data.sha, text, size: data.size || text.length, path: cleanPath };
  } catch (e) {
    const code = e?.statusCode || e?.response?.statusCode || e?.response?.body?.status;
    if (code === 404) {
      return { exists: false, sha: null, text: '', size: 0, path: cleanPath };
    }
    throw e;
  }
}

async function putContent(path, text, message, sha = null) {
  const cleanPath = String(path || '').replace(/^\/+/, '');
  const body = {
    message,
    content: Buffer.from(String(text || ''), 'utf8').toString('base64'),
    branch,
  };
  if (sha) body.sha = sha;

  return await this.helpers.httpRequest({
    method: 'PUT',
    url: `${repoBase}/contents/${encodeURIComponent(cleanPath)}`,
    headers: {
      ...ghHeaders,
      'Content-Type': 'application/json',
    },
    body,
    json: true,
    timeout: 60000,
  });
}

async function listTree() {
  const treeData = await ghGet(`${repoBase}/git/trees/${encodeURIComponent(branch)}?recursive=1`);
  return (treeData.tree || []).filter((item) => item.type === 'blob');
}

function filterMemoryMd(tree) {
  const base = `${basePath}/`;
  const archivePrefix = `${basePath}/${archiveRoot}/`;
  return tree
    .filter((f) => f.path && f.path.endsWith('.md'))
    .filter((f) => f.path.startsWith(base))
    .filter((f) => !f.path.startsWith(archivePrefix));
}

function buildEntry(content, meta = null) {
  const now = nowIso();
  const metaLine = meta && Object.keys(meta).length
    ? `- meta: ${JSON.stringify(meta)}`
    : null;
  const lines = [
    `## ${now}`,
    metaLine,
    String(content || '').trim(),
    '',
  ].filter(Boolean);
  return lines.join('\n');
}

try {
  if (!githubToken) {
    return [{
      json: {
        ...cfg,
        status: 'error',
        output: 'MEMORY_AGENT: отсутствует MEMORY_GITHUB_TOKEN.',
      },
    }];
  }

  const startedAt = nowIso();

  if (action === 'upsert' || action === 'write' || action === 'append') {
    const path = buildMemoryPath();
    const content = String(cfg.content || cfg.text || cfg.note || '').trim();
    if (!content) {
      return [{ json: { ...cfg, status: 'error', output: 'MEMORY_AGENT: для upsert нужен content/text.' } }];
    }

    const current = await getContent.call(this, path);
    const title = `# Memory: ${path.split('/').pop().replace(/\.md$/, '')}`;
    const meta = cfg.meta && typeof cfg.meta === 'object' ? cfg.meta : null;
    const entry = buildEntry(content, meta);

    const nextText = current.exists
      ? `${String(current.text || '').replace(/\s+$/, '')}\n\n${entry}\n`
      : `${title}\n\n${entry}\n`;

    const res = await putContent.call(this, path, nextText, `feat(memory): upsert ${path}`, current.sha);
    return [{
      json: {
        ...cfg,
        status: 'ok',
        action: 'upsert',
        memory_path: path,
        commit_sha: res?.commit?.sha || '',
        output: `MEMORY_AGENT: запись обновлена (${path}).`,
      },
    }];
  }

  if (action === 'get_file' || action === 'read') {
    const path = buildMemoryPath();
    const file = await getContent.call(this, path);
    if (!file.exists) {
      return [{ json: { ...cfg, status: 'error', action: 'get_file', output: `MEMORY_AGENT: файл не найден (${path}).` } }];
    }
    const maxChars = Number(cfg.max_chars || 12000);
    const text = String(file.text || '');
    return [{
      json: {
        ...cfg,
        status: 'ok',
        action: 'get_file',
        memory_path: path,
        content: text.length > maxChars ? `${text.slice(0, maxChars)}\n\n...[truncated]` : text,
        output: `MEMORY_AGENT: файл прочитан (${path}).`,
      },
    }];
  }

  if (action === 'list_files') {
    const tree = await listTree.call(this);
    const files = filterMemoryMd(tree)
      .sort((a, b) => (b.size || 0) - (a.size || 0))
      .slice(0, maxScanFiles)
      .map((f) => ({ path: f.path, size: f.size || 0 }));

    return [{
      json: {
        ...cfg,
        status: 'ok',
        action: 'list_files',
        files,
        output: `MEMORY_AGENT: найдено файлов ${files.length}.`,
      },
    }];
  }

  if (action === 'search' || action === 'find') {
    const query = String(cfg.query || cfg.key || '').trim().toLowerCase();
    const keyFilter = String(cfg.memory_key || cfg.key_filter || '').trim().toLowerCase();
    const fromDate = parseDate(cfg.from_date);
    const toDate = parseDate(cfg.to_date);

    const tree = await listTree.call(this);
    const files = filterMemoryMd(tree).slice(0, maxScanFiles);

    const results = [];

    for (const file of files) {
      const content = await getContent.call(this, file.path);
      const lines = String(content.text || '').split(/\r?\n/);

      let currentSectionDate = null;
      for (let i = 0; i < lines.length; i += 1) {
        const line = lines[i];
        const sectionMatch = line.match(/^##\s+(.+)$/);
        if (sectionMatch) {
          currentSectionDate = parseDate(sectionMatch[1]);
          continue;
        }

        const lowLine = line.toLowerCase();
        const queryMatch = query ? lowLine.includes(query) : true;
        const keyMatch = keyFilter ? file.path.toLowerCase().includes(keyFilter) || lowLine.includes(keyFilter) : true;
        const dateMatch = inRange(currentSectionDate, fromDate, toDate);

        if (queryMatch && keyMatch && dateMatch) {
          results.push({
            path: file.path,
            date: currentSectionDate ? currentSectionDate.toISOString() : '',
            snippet: makeSnippet(lines, i, 2),
          });
          if (results.length >= maxResults) break;
        }
      }

      if (results.length >= maxResults) break;
    }

    return [{
      json: {
        ...cfg,
        status: 'ok',
        action: 'search',
        matches: results.length,
        results,
        output: `MEMORY_AGENT: найдено совпадений ${results.length}.`,
      },
    }];
  }

  if (action === 'archive_weekly') {
    const tree = await listTree.call(this);
    const files = filterMemoryMd(tree).slice(0, maxArchiveFiles);
    const weekId = getWeekId(new Date());

    const archived = [];
    for (const file of files) {
      const content = await getContent.call(this, file.path);
      if (!content.exists) continue;
      const rel = file.path.slice(`${basePath}/`.length);
      const archivePath = `${basePath}/${archiveRoot}/weekly/${weekId}/${rel}`;
      const archiveBody = [
        `# Weekly Archive Snapshot`,
        `- source: ${file.path}`,
        `- archived_at: ${startedAt}`,
        '',
        content.text,
      ].join('\n');

      await putContent.call(this, archivePath, archiveBody, `chore(memory): weekly archive ${rel}`);
      archived.push({ source: file.path, archive: archivePath });
    }

    return [{
      json: {
        ...cfg,
        status: 'ok',
        action: 'archive_weekly',
        archived_count: archived.length,
        archived,
        output: `MEMORY_AGENT: weekly archive готов, файлов: ${archived.length}.`,
      },
    }];
  }

  if (action === 'compact' || action === 'sync' || action === 'health_check') {
    const tree = await listTree.call(this);
    const files = filterMemoryMd(tree);
    const totalBytes = files.reduce((acc, f) => acc + Number(f.size || 0), 0);
    const oversized = files.filter((f) => Number(f.size || 0) > maxFileBytes);

    const compacted = [];
    if (action === 'compact' || action === 'sync') {
      for (const file of oversized.slice(0, maxCompactFiles)) {
        const content = await getContent.call(this, file.path);
        if (!content.exists) continue;
        const lines = String(content.text || '').split(/\r?\n/);
        if (lines.length <= keepRecentLines + 20) continue;

        const keep = lines.slice(-keepRecentLines).join('\n');
        const moved = lines.slice(0, -keepRecentLines).join('\n');
        const movedCount = Math.max(0, lines.length - keepRecentLines);
        const archPath = `${basePath}/${archiveRoot}/compacted/${datePart(startedAt)}/${file.path.slice(`${basePath}/`.length)}`;

        const archiveBody = [
          '# Compacted Segment',
          `- source: ${file.path}`,
          `- compacted_at: ${startedAt}`,
          `- moved_lines: ${movedCount}`,
          '',
          moved,
        ].join('\n');

        await putContent.call(this, archPath, archiveBody, `chore(memory): compact archive ${file.path}`);

        const compactBody = [
          '# Compacted Memory File',
          `- compacted_at: ${startedAt}`,
          `- archive_path: ${archPath}`,
          `- kept_lines: ${keepRecentLines}`,
          '',
          keep,
          '',
        ].join('\n');

        await putContent.call(this, file.path, compactBody, `chore(memory): compact ${file.path}`, content.sha);
        compacted.push({ path: file.path, archive: archPath, moved_lines: movedCount });
      }
    }

    const hbPath = `${basePath}/${heartbeatRel}`;
    const hbOld = await getContent.call(this, hbPath);
    const prevSyncMatch = String(hbOld.text || '').match(/last_sync:\s*(.+)$/m);
    const prevSync = prevSyncMatch ? parseDate(prevSyncMatch[1]) : null;
    const staleDays = Number(cfg.stale_days || 2);
    const staleBeforeSync = prevSync
      ? ((Date.now() - prevSync.getTime()) / 86400000) > staleDays
      : true;

    if (action === 'sync' || action === 'health_check') {
      const hb = [
        '# Memory Agent Heartbeat',
        `- last_sync: ${startedAt}`,
        `- repo: ${owner}/${repo}`,
        `- branch: ${branch}`,
        `- base_path: ${basePath}`,
        `- total_files: ${files.length}`,
        `- total_bytes: ${totalBytes}`,
        `- max_repo_bytes: ${maxRepoBytes}`,
        `- oversized_files: ${oversized.length}`,
        `- compacted_now: ${compacted.length}`,
        `- stale_before_sync: ${staleBeforeSync}`,
        '',
      ].join('\n');

      await putContent.call(this, hbPath, hb, 'chore(memory): heartbeat sync', hbOld.sha);
    }

    const exceeded = totalBytes > maxRepoBytes || oversized.length > 0;
    return [{
      json: {
        ...cfg,
        status: 'ok',
        action,
        total_files: files.length,
        total_bytes: totalBytes,
        exceeded,
        oversized_count: oversized.length,
        compacted_count: compacted.length,
        compacted,
        stale_before_sync: staleBeforeSync,
        output: `MEMORY_AGENT: ${action} выполнен. files=${files.length}, bytes=${totalBytes}, compacted=${compacted.length}.`,
      },
    }];
  }

  return [{
    json: {
      ...cfg,
      status: 'error',
      output: `MEMORY_AGENT: неизвестное action=${action}. Поддержка: upsert, get_file, list_files, search, archive_weekly, compact, sync, health_check.`,
    },
  }];
} catch (e) {
  return [{
    json: {
      ...cfg,
      status: 'error',
      action,
      error: e.message || String(e),
      output: `MEMORY_AGENT: ошибка GitHub-движка: ${e.message || 'unknown'}`,
    },
  }];
}

const cfg = $input.first().json || {};
const backend = String(cfg.storage_backend || '').toLowerCase();

const urlMap = {
  gdrive: String(cfg.connector_gdrive_url || ''),
  dropbox: String(cfg.connector_dropbox_url || ''),
  s3: String(cfg.connector_s3_url || ''),
};

const connectorUrl = urlMap[backend] || '';

if (!connectorUrl) {
  return [{
    json: {
      ...cfg,
      status: 'error',
      output: `MEMORY_AGENT: для backend=${backend} не настроен connector URL.`,
    },
  }];
}

try {
  const payload = {
    action: cfg.action || 'sync',
    memory_key: cfg.memory_key || '',
    path: cfg.path || '',
    query: cfg.query || '',
    from_date: cfg.from_date || '',
    to_date: cfg.to_date || '',
    content: cfg.content || cfg.text || '',
    options: {
      max_results: cfg.max_results,
      max_file_bytes: cfg.max_file_bytes,
      keep_recent_lines: cfg.keep_recent_lines,
    },
  };

  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: connectorUrl,
    headers: {
      'Content-Type': 'application/json',
      ...(cfg.connector_auth_token ? { Authorization: `Bearer ${cfg.connector_auth_token}` } : {}),
    },
    body: payload,
    json: true,
    timeout: 60000,
  });

  return [{
    json: {
      ...cfg,
      status: 'ok',
      output: `MEMORY_AGENT: connector backend=${backend} отработал успешно.`,
      connector_response: res,
    },
  }];
} catch (e) {
