    },
  }];
}

const cfg = $input.first().json || {};
const backend = String(cfg.storage_backend || 'github').toLowerCase();
const missing = [];

if (backend === 'github') {
  const token = String(cfg.github_token || '').trim();
  if (!token || token.length < 20 || token.includes('REPLACE_')) {
    missing.push('MEMORY_GITHUB_TOKEN');
