}

if (backend === 'gdrive' && !String(cfg.connector_gdrive_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_GDRIVE_URL');
}
if (backend === 'dropbox' && !String(cfg.connector_dropbox_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_DROPBOX_URL');
}
if (backend === 's3' && !String(cfg.connector_s3_url || '').trim()) {
  missing.push('MEMORY_CONNECTOR_S3_URL');
}

const validateStatus = missing.length ? 'error' : 'ok';
const output = validateStatus === 'ok'
  ? `MEMORY_AGENT: конфиг валиден, backend=${backend}, action=${cfg.action || 'sync'}.`
  : `MEMORY_AGENT: отсутствуют настройки: ${missing.join(', ')}.`;

